package am.ik.yavi.fn;

import org.jspecify.annotations.Nullable;

/**
 * A function that takes 6 arguments and produces a result.
 *
 * <p>
 * This is the 6-argument variant of {@link java.util.function.Function}, used to apply a
 * function to the values of combined validation results. Every argument is annotated
 * {@link org.jspecify.annotations.Nullable}, so implementations must accept {@code null}
 * arguments.
 *
 * <p>
 * Generated by <a href=
 * "https://github.com/making/yavi/blob/develop/scripts/generate-function.sh">generate-function.sh</a>.
 *
 * @param <T1> the type of argument 1
 * @param <T2> the type of argument 2
 * @param <T3> the type of argument 3
 * @param <T4> the type of argument 4
 * @param <T5> the type of argument 5
 * @param <T6> the type of argument 6
 * @param <R> the type of the result
 * @since 0.6.0
 */
@FunctionalInterface
public interface Function6<T1, T2, T3, T4, T5, T6, R> {

	/**
	 * Applies this function to the given arguments.
	 * @param t1 argument 1, possibly {@code null}
	 * @param t2 argument 2, possibly {@code null}
	 * @param t3 argument 3, possibly {@code null}
	 * @param t4 argument 4, possibly {@code null}
	 * @param t5 argument 5, possibly {@code null}
	 * @param t6 argument 6, possibly {@code null}
	 * @return the function result
	 */
	R apply(@Nullable T1 t1, @Nullable T2 t2, @Nullable T3 t3, @Nullable T4 t4, @Nullable T5 t5, @Nullable T6 t6);

}
